BEGIN;

CREATE TABLE IF NOT EXISTS skolenza."InstitutionStaffCategoryMaster" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NULL,
    "TemplateSourceId" integer NULL,
    "StaffCategoryTypeId" smallint NOT NULL,
    "Code" varchar(60) NOT NULL,
    "Name" varchar(150) NOT NULL,
    "Description" varchar(500) NULL,
    "DisplayOrder" smallint NOT NULL DEFAULT 0,
    "IsActive" boolean NOT NULL DEFAULT true,
    "IsSystemDefined" boolean NOT NULL DEFAULT false,
    "AddedById" bigint NULL,
    "AddedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint NULL,
    "UpdatedDateTime" timestamptz NULL,
    "IsSoftDeleted" boolean NOT NULL DEFAULT false,
    "SoftDeletedById" bigint NULL,
    "DeletedDateTime" timestamptz NULL,
    CONSTRAINT "FK_InstitutionStaffCategoryMaster_Institution" FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution"("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_InstitutionStaffCategoryMaster_Type" FOREIGN KEY ("StaffCategoryTypeId") REFERENCES skolenza."StaffCategory"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_InstitutionStaffCategoryMaster_Template" FOREIGN KEY ("TemplateSourceId") REFERENCES skolenza."InstitutionStaffCategoryMaster"("Id") ON DELETE RESTRICT
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_InstitutionStaffCategoryMaster_Platform_Code"
    ON skolenza."InstitutionStaffCategoryMaster" (lower("Code")) WHERE "InstitutionId" IS NULL AND NOT "IsSoftDeleted";
CREATE UNIQUE INDEX IF NOT EXISTS "UX_InstitutionStaffCategoryMaster_Institution_Code"
    ON skolenza."InstitutionStaffCategoryMaster" ("InstitutionId", lower("Code")) WHERE "InstitutionId" IS NOT NULL AND NOT "IsSoftDeleted";

CREATE TABLE IF NOT EXISTS skolenza."StaffCategoryJobFamily" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "InstitutionStaffCategoryMasterId" integer NOT NULL,
    "StaffJobFamilyMasterId" integer NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT true,
    "AddedById" bigint NULL,
    "AddedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint NULL,
    "UpdatedDateTime" timestamptz NULL,
    CONSTRAINT "FK_StaffCategoryJobFamily_Institution" FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution"("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_StaffCategoryJobFamily_Category" FOREIGN KEY ("InstitutionStaffCategoryMasterId") REFERENCES skolenza."InstitutionStaffCategoryMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StaffCategoryJobFamily_JobFamily" FOREIGN KEY ("StaffJobFamilyMasterId") REFERENCES skolenza."StaffJobFamilyMaster"("Id") ON DELETE RESTRICT,
    CONSTRAINT "UX_StaffCategoryJobFamily" UNIQUE ("InstitutionId", "InstitutionStaffCategoryMasterId", "StaffJobFamilyMasterId")
);

ALTER TABLE skolenza."StaffPositionMaster" ADD COLUMN IF NOT EXISTS "InstitutionStaffCategoryMasterId" integer NULL;
ALTER TABLE skolenza."StaffMember" ADD COLUMN IF NOT EXISTS "InstitutionStaffCategoryMasterId" integer NULL;

INSERT INTO skolenza."InstitutionStaffCategoryMaster"
    ("InstitutionId", "StaffCategoryTypeId", "Code", "Name", "Description", "DisplayOrder", "IsActive", "IsSystemDefined")
SELECT NULL, category."Id", category."Code", category."Name", category."Description", category."DisplayOrder", category."IsActive", true
FROM skolenza."StaffCategory" category
ON CONFLICT DO NOTHING;

CREATE OR REPLACE FUNCTION skolenza."SeedInstitutionStaffCategoryHierarchy"(
    p_institution_id bigint,
    p_actor_staff_member_id bigint DEFAULT NULL)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO skolenza."InstitutionStaffCategoryMaster"
        ("InstitutionId", "TemplateSourceId", "StaffCategoryTypeId", "Code", "Name", "Description", "DisplayOrder", "IsActive", "IsSystemDefined", "AddedById")
    SELECT p_institution_id, template."Id", template."StaffCategoryTypeId", template."Code", template."Name",
           template."Description", template."DisplayOrder", template."IsActive", false, p_actor_staff_member_id
    FROM skolenza."InstitutionStaffCategoryMaster" template
    WHERE template."InstitutionId" IS NULL AND template."IsActive" AND NOT template."IsSoftDeleted"
    ON CONFLICT DO NOTHING;

    INSERT INTO skolenza."StaffCategoryJobFamily"
        ("InstitutionId", "InstitutionStaffCategoryMasterId", "StaffJobFamilyMasterId", "AddedById")
    SELECT DISTINCT p_institution_id, category."Id", position."StaffJobFamilyMasterId", p_actor_staff_member_id
    FROM skolenza."StaffPositionMaster" position
    JOIN skolenza."InstitutionStaffCategoryMaster" category
      ON category."InstitutionId" = p_institution_id
     AND category."StaffCategoryTypeId" = position."StaffCategoryId"
     AND NOT category."IsSoftDeleted"
    WHERE position."InstitutionId" = p_institution_id AND NOT position."IsSoftDeleted"
    ON CONFLICT DO NOTHING;

    UPDATE skolenza."StaffPositionMaster" position
    SET "InstitutionStaffCategoryMasterId" = category."Id"
    FROM skolenza."InstitutionStaffCategoryMaster" category
    WHERE position."InstitutionId" = p_institution_id
      AND category."InstitutionId" = p_institution_id
      AND category."StaffCategoryTypeId" = position."StaffCategoryId"
      AND position."InstitutionStaffCategoryMasterId" IS NULL;

    UPDATE skolenza."StaffMember" staff
    SET "InstitutionStaffCategoryMasterId" = category."Id"
    FROM skolenza."InstitutionStaffCategoryMaster" category
    WHERE staff."InstitutionId" = p_institution_id
      AND category."InstitutionId" = p_institution_id
      AND category."StaffCategoryTypeId" = staff."StaffCategoryId"
      AND staff."InstitutionStaffCategoryMasterId" IS NULL;
END;
$$;

DO $$ DECLARE institution_row record; BEGIN
    FOR institution_row IN SELECT "Id" FROM skolenza."Institution" LOOP
        PERFORM skolenza."SeedInstitutionStaffCategoryHierarchy"(institution_row."Id", NULL);
    END LOOP;
END $$;

DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_StaffPositionMaster_InstitutionCategory') THEN
        ALTER TABLE skolenza."StaffPositionMaster"
            ADD CONSTRAINT "FK_StaffPositionMaster_InstitutionCategory"
            FOREIGN KEY ("InstitutionStaffCategoryMasterId") REFERENCES skolenza."InstitutionStaffCategoryMaster"("Id") ON DELETE RESTRICT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_StaffMember_InstitutionCategory') THEN
        ALTER TABLE skolenza."StaffMember"
            ADD CONSTRAINT "FK_StaffMember_InstitutionCategory"
            FOREIGN KEY ("InstitutionStaffCategoryMasterId") REFERENCES skolenza."InstitutionStaffCategoryMaster"("Id") ON DELETE RESTRICT;
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS "IX_StaffPositionMaster_InstitutionCategory" ON skolenza."StaffPositionMaster"("InstitutionStaffCategoryMasterId");
CREATE INDEX IF NOT EXISTS "IX_StaffMember_InstitutionCategory" ON skolenza."StaffMember"("InstitutionStaffCategoryMasterId");

COMMIT;
